ALTER TABLE `Product` ADD COLUMN `version` INTEGER NOT NULL DEFAULT 0;
ALTER TABLE `Order` ADD COLUMN `requestKey` VARCHAR(64) NULL, ADD COLUMN `requestFingerprint` VARCHAR(64) NULL, ADD UNIQUE INDEX `Order_requestKey_key`(`requestKey`);
ALTER TABLE `Consultation` ADD COLUMN `requestKey` VARCHAR(64) NULL, ADD COLUMN `requestFingerprint` VARCHAR(64) NULL, ADD UNIQUE INDEX `Consultation_requestKey_key`(`requestKey`);
CREATE TABLE `RateBucket` (`key` VARCHAR(191) NOT NULL, `count` INTEGER NOT NULL, `expiresAt` DATETIME(3) NOT NULL, PRIMARY KEY (`key`), INDEX `RateBucket_expiresAt_idx` (`expiresAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `NotificationJob` (`id` VARCHAR(191) NOT NULL, `kind` VARCHAR(40) NOT NULL, `recordId` VARCHAR(191) NOT NULL, `status` VARCHAR(20) NOT NULL DEFAULT 'pending', `attempts` INTEGER NOT NULL DEFAULT 0, `nextAttemptAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `lockedUntil` DATETIME(3) NULL, `lockToken` VARCHAR(64) NULL, `lastError` VARCHAR(300) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `NotificationJob_kind_recordId_key` (`kind`, `recordId`), INDEX `NotificationJob_status_nextAttemptAt_idx` (`status`, `nextAttemptAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
